var n=`0486-fatteh`;var t=`world-0486`;var a=`LB`;var r=`western-asia`;var o=4;var s=31;var l={en:`Fatteh`,ua:`Фатте`};var g={en:`A traditional dish from Lebanon, centered on pita bread, canned chickpeas, plain yogurt, tahini. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Ліван. Основні складники: піта, консервований нут, натуральний йогурт, тахіні. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Toast these ingredients over medium heat for about 5 minutes, turning frequently to prevent scorching.`,ua:`Підсмажуйте зазначені складники на середньому вогні приблизно 5 хвилин, часто перевертаючи, щоб не підгоріли.`,t:[`dry-toasting`],m:5,i:[[`pita-bread`,4,`pcs`]]},{en:`Cook the listed ingredients in simmering water for about 12 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 12 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:12,i:[[`canned-chickpeas`,520,`g`],[`water`,280,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:6,i:[[`plain-yogurt`,420,`g`],[`tahini`,85,`g`],[`garlic`,3,`clove`],[`lemon-juice`,45,`ml`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:8,i:[[`extra-virgin-olive-oil`,45,`ml`],[`pine-nut`,60,`g`],[`parsley`,20,`g`]]}];var m={slug:n,id:t,country:`LB`,region:r,servings:4,minutes:31,title:l,text:g,steps:d};export{a as country,m as default,t as id,s as minutes,r as region,o as servings,n as slug,d as steps,g as text,l as title};